n44175.content:
\begin{proof}\leanok
  Let $B:=\sum_{s\in S} b_s$. Apply Jensen and \Cref{concave} to show that $\sum_{s\in S} \frac{b_s}{B} h(\frac{a_s}{b_s})\ge h(\frac{\sum_{s\in S} a_s}{B})$.
\end{proof}

n44177.content:
\begin{proof}\leanok
\uses{concave} By the fact that $h$ is strictly concave and the equality condition of Jensen.
\end{proof}

n44178.content:
\begin{definition}[Entropy]
  \label{entropy-def}
  \lean{ProbabilityTheory.entropy}
  \leanok
  If $X$ is an $S$-valued random variable, the entropy $\mathbb{H}[X]$ of $X$ is defined
  $$ \mathbb{H}[X] := \sum_{s \in S} \mathbb{P}[X=x] \log \frac{1}{\mathbb{P}[X=x]}$$
  with the convention that $0 \log \frac{1}{0} = 0$.
\end{definition}

n44179.content:
\begin{lemma}[Entropy and relabeling]\label{relabeled-entropy}\lean{ProbabilityTheory.entropy_comp_of_injective, ProbabilityTheory.entropy_of_comp_eq_of_comp} \uses{entropy-def}\leanok
  \begin{itemize}
\item[(i)]   If $X: \Omega \to S$ and $Y: \Omega \to T$ are random variables, and $Y = f(X)$ for some injection $f: S \to T$, then $\mathbb{H}[X] = \mathbb{H}[Y]$.
\item[(ii)]   If $X: \Omega \to S$ and $Y: \Omega \to T$ are random variables, and $Y = f(X)$ and $X = g(Y)$ for some functions $f: S \to T$, $g: T \to S$, then $\mathbb{H}[X] = \mathbb{H}[Y]$.
\end{itemize}
\end{lemma}

n44181.content:
\begin{lemma}[Jensen bound]\label{jensen-bound}
  \uses{entropy-def}
  \lean{ProbabilityTheory.entropy_le_log_card, ProbabilityTheory.entropy_le_log_card_of_mem}
  \leanok
  If $X$ is an $S$-valued random variable, then $\mathbb{H}[X] \leq \log |S|$.
\end{lemma}

n44182.content:
\begin{proof}
  \uses{concave}
  \leanok

  This is a direct consequence of \Cref{concave} and Jensen's inequality.
\end{proof}

n44183.content:
\begin{definition}[Uniform distribution]\label{uniform-def}\leanok
  \lean{ProbabilityTheory.IsUniform} If $H$ is a subset of $S$, an $S$-random variable $X$ is said to be uniformly distributed on $H$ if $\mathbb{P}[X = s] = 1/|H|$ for $s \in X$ and $\mathbb{P}[X=s] = 0$ otherwise.
\end{definition}

n44184.content:
\begin{lemma}[Uniform distributions exist]\label{unif-exist}
  \uses{uniform-def}
  \lean{ProbabilityTheory.exists_isUniform, ProbabilityTheory.exists_isUniform_measureSpace}\leanok
  Given a finite non-empty subset $H$ of a set $S$, there exists a random variable $X$ (on some probability space) that is uniformly distributed on $H$.
\end{lemma}

n44186.content:
\begin{lemma}[Entropy of uniform random variable]\label{uniform-entropy}
  \uses{entropy-def}
  \lean{ProbabilityTheory.IsUniform.entropy_eq}\leanok
  If $X$ is $S$-valued random variable, then $\mathbb{H}[X] = \log |S|$ if and only if $X$ is uniformly distributed on $S$.
\end{lemma}

n44187.content:
\begin{proof}
  \uses{concave}
  \leanok

  Direct computation in one direction.
  Converse direction needs the strict Jensen inequality and \Cref{concave}.
\end{proof}

n44188.content:
\begin{lemma}[Entropy of uniform random variable, II]\label{uniform-entropy-II}
  \uses{entropy-def, uniform-def}
  \lean{ProbabilityTheory.IsUniform.entropy_eq}\leanok
  If $X$ is uniformly distributed on $H$, then, then $\mathbb{H}[X] = \log |H|$.
\end{lemma}

n44190.content:
\begin{lemma}[Bounded entropy implies concentration]\label{bound-conc}
  \uses{entropy-def}
  \lean{ProbabilityTheory.prob_ge_exp_neg_entropy}\leanok
  If $X$ is an $S$-valued random variable, then there exists $s \in S$ such that $\mathbb{P}[X=s] \geq \exp(-\mathbb{H}[X])$.
\end{lemma}

n44191.content:
\begin{proof}
  \leanok
  We have
  $$ \mathbb{H}[X] = \sum_{s \in S} \mathbb{P}[X=s] \log \frac{1}{\mathbb{P}[X=s]} \geq \min_{s \in S} \log \frac{1}{\mathbb{P}[X=s]}$$
  and the claim follows.
\end{proof}

n44192.content:
\begin{lemma}[Commutativity and associativity of joint entropy]
  \label{entropy-comm}
  \lean{ProbabilityTheory.entropy_comm, ProbabilityTheory.entropy_assoc}
  \leanok
  If $X: \Omega \to S$, $Y: \Omega \to T$, and $Z: \Omega \to U$ are random variables, then $\mathbb{H}[X, Y] = \mathbb{H}[Y, X]$ and $\mathbb{H}[X, (Y,Z)] = \mathbb{H}[(X,Y), Z]$.
\end{lemma}

n44193.content:
\begin{proof}
  \leanok
  \uses{relabeled-entropy}
  Set up an injection from $(X,Y)$ to $(Y,X)$ and use \Cref{relabeled-entropy} for the first claim. Similarly for the second claim.
\end{proof}

n44194.content:
\begin{definition}[Conditioned event]
  \label{condition-event-def}
  \lean{ProbabilityTheory.cond}
  \leanok
  If $X: \Omega \to S$ is an $S$-valued random variable and $E$ is an event in $\Omega$, then the conditioned event $(X|E)$ is defined to be the same random variable as $X$, but now the ambient probability measure has been conditioned to $E$.
\end{definition}

n44195.content:
\begin{definition}[Conditional entropy]
  \label{conditional-entropy-def}
  \uses{entropy-def,condition-event-def}
  \lean{ProbabilityTheory.condEntropy}
  \leanok
  If $X: \Omega \to S$ and $Y: \Omega \to T$ are random variables, the conditional entropy $\mathbb{H}[X|Y]$ is defined as
  $$ \mathbb{H}[X|Y] := \sum_{y \in Y} \mathbb{P}[Y = y] \mathbb{H}[(X | Y=y)].$$
\end{definition}

n44196.content:
\begin{lemma}[Conditional entropy and relabeling]\label{relabeled-entropy-cond}
  \uses{conditional-entropy-def}
  \lean{ProbabilityTheory.condEntropy_comp_of_injective, ProbabilityTheory.condEntropy_of_injective'}\leanok
  If $X: \Omega \to S$, $Y: \Omega \to T$, and $Z: \Omega \to U$ are random variables, and $Y = f(X,Z)$ almost surely for some map $f: S \times U \to T$ that is injective for each fixed $U$, then $\mathbb{H}[X|Z] = \mathbb{H}[Y|Z]$.

  Similarly, if $g: T \to U$ is injective, then $\mathbb{H}[X|g(Y)] = \mathbb{H}[X|Y]$.
\end{lemma}

n44197.content:
\begin{proof}
  \uses{relabeled-entropy}\leanok
  For the first part, use \Cref{conditional-entropy-def} and then \Cref{relabeled-entropy}.  The second part is a direct computation.
\end{proof}

n44198.content:
\begin{lemma}[Chain rule]\label{chain-rule}
  \uses{conditional-entropy-def}
  \lean{ProbabilityTheory.chain_rule, ProbabilityTheory.chain_rule'}
  \leanok
  If $X: \Omega \to S$ and $Y: \Omega \to T$ are random variables, then
  $$ \mathbb{H}[X, Y] = \mathbb{H}[Y] + \mathbb{H}[X|Y].$$
  \end{lemma}

n44200.content:
\begin{lemma}[Conditional chain rule]\label{conditional-chain-rule}
  \lean{ProbabilityTheory.cond_chain_rule, ProbabilityTheory.cond_chain_rule'}\leanok
  If $X: \Omega \to S$, $Y: \Omega \to T$, $Z: \Omega \to U$ are random variables, then
$$ \mathbb{H}[X, Y | Z] = \mathbb{H}[Y | Z] + \mathbb{H}[X|Y, Z].$$
\end{lemma}

n44202.content:
\begin{definition}[Mutual information]
  \label{information-def}
  \uses{entropy-def}
  \lean{ProbabilityTheory.mutualInfo, ProbabilityTheory.mutualInfo_def}
  \leanok
  If $X: \Omega \to S$, $Y: \Omega \to T$ are random variables, then
  $$\mathbb{I}[X : Y] := \mathbb{H}[X] + \mathbb{H}[Y] - \mathbb{H}[X,Y].$$
\end{definition}

n44203.content:
\begin{lemma}[Alternative formulae for mutual information]
  \label{alternative-mutual}
  \uses{information-def}
  \lean{ProbabilityTheory.mutualInfo_comm, ProbabilityTheory.mutualInfo_eq_entropy_sub_condEntropy}
  \leanok
  With notation as above, we have
  $$  \mathbb{I}[X : Y] = \mathbb{I}[Y:X]$$
  $$  \mathbb{I}[X : Y] = \mathbb{H}[X] - \mathbb{H}[X|Y]$$
  $$  \mathbb{I}[X : Y] = \mathbb{H}[Y] - \mathbb{H}[Y|X]$$
\end{lemma}

n44206.content:
\begin{proof}
  \uses{concave, alternative-mutual}
  \leanok

  An application of jensen's inequality and \Cref{concave,alternative-mutual}.
\end{proof}

n44207.content:
\begin{corollary}[Subadditivity]
  \label{subadditive}
  \lean{ProbabilityTheory.entropy_pair_le_add}
  \leanok
  With notation as above, we have $\mathbb{H}[X,Y] \leq \mathbb{H}[X] + \mathbb{H}[Y]$.
\end{corollary}

n44209.content:
\begin{corollary}[Conditioning reduces entropy]
  \label{cond-reduce}
  \lean{ProbabilityTheory.condEntropy_le_entropy}
  \leanok
  With notation as above, we have $\mathbb{H}[X|Y] \leq \mathbb{H}[X]$.
\end{corollary}

n44211.content:
\begin{corollary}[Submodularity]\label{submodularity}
  \lean{ProbabilityTheory.entropy_submodular, ProbabilityTheory.condEntropy_comp_ge}\leanok
  With three random variables $X,Y,Z$, one has $\mathbb{H}[X|Y,Z] \leq \mathbb{H}[X|Z]$.
\end{corollary}

n44213.content:
\begin{corollary}[Alternate form of submodularity]\label{alt-submodularity}
  \lean{ProbabilityTheory.entropy_triple_add_entropy_le}\leanok
  With three random variables $X,Y,Z$, one has
  $$ \mathbb{H}[X,Y,Z] + \mathbb{H}[Z] \leq \mathbb{H}[X,Z] + \mathbb{H}[Y,Z].$$
\end{corollary}

n44215.content:
\begin{definition}[Independent random variables]
  \label{independent-def}
  \lean{ProbabilityTheory.IndepFun}
  \leanok
  Two random variables $X: \Omega \to S$ and $Y: \Omega \to T$ are independent if the law of $(X,Y)$ is the product of the law of $X$ and the law of $Y$.  Similarly for more than two variables.
\end{definition}

n44216.content:
\begin{lemma}[Vanishing of mutual information]
  \label{vanish-entropy}
  \uses{information-def, independent-def}
  \lean{ProbabilityTheory.mutualInfo_eq_zero}
  \leanok
  If $X,Y$ are random variables, then $\mathbb{I}[X:Y] = 0$ if and only if $X,Y$ are independent.
  \end{lemma}

n44217.content:
\begin{proof}
    \uses{concave}
    \leanok

    An application of the equality case of Jensen's inequality and \Cref{concave}.
  \end{proof}

n44218.content:
\begin{corollary}[Additivity of entropy]\label{add-entropy}
  \lean{ProbabilityTheory.entropy_pair_eq_add}
  \leanok
  If $X,Y$ are random variables, then $\mathbb{H}[X,Y] = \mathbb{H}[X] + \mathbb{H}[Y]$ if and only if $X,Y$ are independent.
\end{corollary}

n44220.content:
\begin{definition}[Conditional mutual information]
\label{conditional-mutual-def}
\uses{information-def,condition-event-def}
\lean{ProbabilityTheory.condMutualInfo}
\leanok
If $X,Y,Z$ are random variables, with $Z$ $U$-valued, then
$$ \mathbb{I}[X:Y|Z] := \sum_{z \in U} P[Z=z] \mathbb{I}[(X|Z=z): (Y|Z=z)].$$
\end{definition}

n44221.content:
\begin{lemma}[Alternate formula for conditional mutual information]
  \label{conditional-mutual-alt}
  \uses{conditional-mutual-def}
  \lean{ProbabilityTheory.condMutualInfo_eq, ProbabilityTheory.condMutualInfo_eq'}\leanok
We have
  $$ \mathbb{I}[X:Y|Z] := \mathbb{H}[X|Z] + \mathbb{H}[Y|Z] - \mathbb{H}[X,Y|Z]$$
and
  $$ \mathbb{I}[X:Y|Z] := \mathbb{H}[X|Z] - \mathbb{H}[X|Y,Z].$$
\end{lemma}

n44223.content:
\begin{lemma}[Nonnegativity of conditional mutual information]
\label{conditional-nonneg}
\uses{conditional-mutual-def}
\lean{ProbabilityTheory.condMutualInfo_nonneg}\leanok
If $X,Y,Z$ are random variables, then $\mathbb{I}[X:Y|Z] \ge 0$.
\end{lemma}

n44225.content:
\begin{definition}[Conditionally independent random variables]
\label{conditional-independent-def}
\lean{ProbabilityTheory.CondIndepFun}\leanok
  Two random variables $X: \Omega \to S$ and $Y: \Omega \to T$ are conditionally independent relative to another random variable $Z: \Omega \to U$ if $P[X = s \wedge Y = t| Z=u] = P[X=s|Z=u] P[Y=t|Z=u]$ for all $s \in S, t \in T, u \in U$.  (We won't need conditional independence for more variables than this.)
\end{definition}

n44226.content:
\begin{lemma}[Vanishing conditional mutual information]\label{conditional-vanish}
  \lean{ProbabilityTheory.condMutualInfo_eq_zero}
  \leanok
  If $X,Y,Z$ are random variables, then $\mathbb{I}[X:Y|Z] = 0$ iff $X,Y$ are conditionally independent over $Z$.
\end{lemma}

n44228.content:
\begin{corollary}[Entropy of conditionally independent variables]\label{cond-trial-ent}
  \lean{ProbabilityTheory.ent_of_cond_indep}\leanok
  If $X, Y$ are conditionally independent over $Z$, then
  $$ \mathbb{H}[X,Y,Z] =\mathbb{H}[X,Z] + \mathbb{H}[Y,Z] - \mathbb{H}[Z].$$
\end{corollary}

n44232.content:
\begin{lemma}[Shearing preserves entropy]\label{shear-ent}
  \lean{ProbabilityTheory.condEntropy_add_right, ProbabilityTheory.condEntropy_add_left, ProbabilityTheory.condEntropy_sub_right, ProbabilityTheory.condEntropy_sub_left}\leanok
  If $X,Y$ are $G$-valued, then $\mathbb{H}[X \pm Y | Y]=\mathbb{H}[X|Y]$ and $\mathbb{H}[X \pm Y, Y] = \mathbb{H}[X, Y]$.
\end{lemma}

n44234.content:
\begin{lemma}[Lower bound of sumset]\label{sumset-lower-gen}
  \lean{ProbabilityTheory.max_entropy_sub_mutualInfo_le_entropy_add, ProbabilityTheory.max_entropy_sub_mutualInfo_le_entropy_sub}\leanok
  If $X,Y$ are $G$-valued random variables on $\Omega$, we have
$$ \max(\mathbb{H}[X], \mathbb{H}[Y]) -  \mathbb{I}[X:Y] \leq \mathbb{H}[X \pm Y].$$
\end{lemma}

n44236.content:
\begin{corollary}[Conditional lower bound on sumset]\label{sumset-lower-gen-cond}
  \uses{conditional-mutual-def}
  \lean{ProbabilityTheory.max_condEntropy_sub_condMutualInfo_le_condEntropy_mul, ProbabilityTheory.max_condEntropy_sub_condMutualInfo_le_condEntropy_div}\leanok
  If $X,Y$ are $G$-valued random variables on $\Omega$ and $Z$ is another random variable on $\Omega$ then
\[
  \max(\mathbb{H}[X|Z], \mathbb{H}[Y|Z]) -  \mathbb{I}[X:Y|Z] \leq \mathbb{H}[X\pm Y|Z],
\]
\end{corollary}

n44238.content:
\begin{corollary}[Independent lower bound on sumset]
  \label{sumset-lower}
  \lean{ProbabilityTheory.max_entropy_le_entropy_add, ProbabilityTheory.max_entropy_le_entropy_sub}
  \leanok

  If $X,Y$ are independent $G$-valued random variables, then
  $$\max(\mathbb{H}[X], \mathbb{H}[Y]) \leq \mathbb{H}[X\pm Y]. $$
\end{corollary}

n44240.content:
\begin{lemma}[Copy preserves entropy]\label{copy-ent}
  \uses{entropy-def}
  \lean{ProbabilityTheory.IdentDistrib.entropy_congr}\leanok
  If $X'$ is a copy of $X$ then $\mathbb{H}[X'] = \mathbb{H}[X]$.
\end{lemma}

n44242.content:
\begin{lemma}[Existence of independent copies]\label{independent-exist}
  \uses{independent-def}
  \lean{ProbabilityTheory.independent_copies, ProbabilityTheory.independent_copies', ProbabilityTheory.independent_copies_two, ProbabilityTheory.independent_copies3_nondep} \leanok
  Let $X_i : \Omega_i \to S_i$ be random variables for $i=1,\dots,k$.  Then if one gives $\prod_{i=1}^k S_i$ the product measure of the laws of $X_i$, the coordinate functions $(x_j)_{j=1}^k \mapsto x_i$ are jointly independent random variables which are copies of the $X_1,\dots,X_k$.
\end{lemma}

n44244.content:
\begin{definition}[Ruzsa distance]\label{ruz-dist-def}
  \uses{entropy-def, independent-exist}
  \lean{rdist_def}\leanok
  Let $X,Y$ be $G$-valued random variables (not necessarily on the same sample space).  The \emph{Ruzsa distance} $d[X ;Y]$ between $X$ and $Y$ is defined to be
$$ d[X ;Y] := \mathbb{H}[X' - Y'] - \mathbb{H}[X']/2 - \mathbb{H}[Y']/2$$
where $X',Y'$ are (the canonical) independent copies of $X,Y$ from \Cref{independent-exist}.
\end{definition}

n44245.content:
\begin{lemma}[Distance from zero]\label{dist-zero}
  \uses{ruz-dist-def}\lean{rdist_zero_eq_half_ent}\leanok
If $X$ is a $G$-valued random variable and $0$ is the random variable taking the value $0$ everywhere then
\[d[X;0]=\mathbb{H}(X)/2.\]
\end{lemma}

n44246.content:
\begin{proof}\leanok
This is an immediate consequence of the definitions and $X-0\equiv X$ and $\mathbb{H}(0)=0$.
\end{proof}

n44247.content:
\begin{lemma}[Copy preserves Ruzsa distance]\label{ruz-copy}
  \uses{ruz-dist-def}
  \lean{ProbabilityTheory.IdentDistrib.rdist_congr}\leanok
  If $X',Y'$ are copies of $X,Y$ respectively then $d[X';Y']=d[X ;Y]$.
\end{lemma}

n44249.content:
\begin{lemma}[Ruzsa distance in independent case]\label{ruz-indep}
  \uses{ruz-dist-def}
  \lean{ProbabilityTheory.IndepFun.rdist_eq}\leanok
  If $X,Y$ are independent $G$-random variables then
  $$ d[X ;Y] := \mathbb{H}[X - Y] - \mathbb{H}[X]/2 - \mathbb{H}[Y]/2.$$
\end{lemma}

n44251.content:
\begin{lemma}[Distance symmetric]\label{ruzsa-symm}
  \uses{ruz-dist-def}
  \lean{rdist_symm}\leanok
  If $X,Y$ are $G$-valued random variables, then
  $$ d[X ;Y] = d[Y;X].$$
\end{lemma}

n44253.content:
\begin{lemma}[Distance controls entropy difference]\label{ruzsa-diff}
  \uses{ruz-dist-def}
  \lean{diff_ent_le_rdist}\leanok
  If $X,Y$ are $G$-valued random variables, then
$$|\mathbb{H}[X]-H[Y]| \leq 2 d[X ;Y].$$
\end{lemma}

n44255.content:
\begin{lemma}[Distance controls entropy growth]\label{ruzsa-growth}
  \uses{ruz-dist-def}
  \lean{diff_ent_le_rdist', diff_ent_le_rdist''}\leanok
  If $X,Y$ are independent $G$-valued random variables, then
$$  \mathbb{H}[X-Y] - \mathbb{H}[X], \mathbb{H}[X-Y] - \mathbb{H}[Y] \leq 2d[X ;Y].$$
\end{lemma}

n44257.content:
\begin{lemma}[Distance nonnegative]\label{ruzsa-nonneg}
  \lean{rdist_nonneg}\leanok
  If $X,Y$ are $G$-valued random variables, then
  $$ d[X ;Y] \geq 0.$$
\end{lemma}

n44260.content:
\begin{proof}
\uses{independent-exist, ruzsa-diff, chain-rule, shear-ent, submodularity, jensen-bound}\leanok
WLOG, we make $X$, $U_H$ independent (\Cref{independent-exist}).
Now by Lemmas \ref{submodularity}, \ref{shear-ent}, \ref{jensen-bound}
\begin{align*}
&\mathbb{H}(X-U_H|\pi(X)) \geq \mathbb{H}(X-U_H|X) &= \mathbb{H}(U_H) \\
&\mathbb{H}(X-U_H|\pi(X)) \leq \log |H| &= \mathbb{H}(U_H)
\end{align*}
By \Cref{chain-rule}
\[\mathbb{H}(X-U_H)=\mathbb{H}(\pi(X))+\mathbb{H}(X-U_H|\pi(X))=\mathbb{H}(\pi(X))+\mathbb{H}(U_H)\]
and therefore
\[d[X;U_H]=\mathbb{H}(\pi(X))+\frac{\mathbb{H}(U_H)-\mathbb{H}(X)}{2}.\]
Furthermore by \Cref{ruzsa-diff}
\[d[X;U_H]\geq \frac{\lvert \mathbb{H}(X)-\mathbb{H}(U_H)\rvert}{2}.\]
Adding these inequalities gives the result.
\end{proof}

n44261.content:
\begin{lemma}[Improved Ruzsa triangle inequality]
  \label{ruzsa-triangle-improved}
  \lean{ent_of_diff_le}
  \leanok
  If $X,Y,Z$ are $G$-valued random variables on $\Omega$ with $(X,Y)$ independent of $Z$, then
  \begin{equation}\label{submod-explicit} \mathbb{H}[X - Y] \leq \mathbb{H}[X-Z] + \mathbb{H}[Z-Y] - \mathbb{H}[Z]\end{equation}
\end{lemma}

n44263.content:
\begin{lemma}[Ruzsa triangle inequality]
  \label{ruzsa-triangle}
  \lean{rdist_triangle}
  \leanok
  If $X,Y,Z$ are $G$-valued random variables, then
$$ d[X ;Y] \leq d[X ;Z] + d[Z;Y].$$
\end{lemma}

n44265.content:
\begin{definition}[Conditioned Ruzsa distance]\label{cond-dist-def}
  \uses{ruz-dist-def}
  \lean{condRuzsaDist}\leanok
If $(X, Z)$ and $(Y, W)$ are random variables (where $X$ and $Y$ are $G$-valued) we define
$$ d[X  | Z; Y | W] := \sum_{z,w}  \mathbb{P}[Z=z]  \mathbb{P}[W=w] d[(X|Z=z); (Y|(W=w))].$$
similarly
$$ d[X ; Y | W] := \sum_{w}  \mathbb{P}[W=w] d[X ; (Y|(W=w))].$$
\end{definition}

n44270.content:
\begin{lemma}[Existence of conditional independent trials]\label{cond-indep-exist}
  \uses{conditional-independent-def}
  \lean{ProbabilityTheory.condIndep_copies}\leanok
  For $X,Y$ random variables, there exist random variables $X_1,X_2,Y'$ on a common probability space with $(X_1, Y'), (X_2, Y')$ both having the distribution of $(X,Y)$, and $X_1, X_2$ conditionally independent over $Y'$ in the sense of \Cref{conditional-independent-def}.
\end{lemma}

n44272.content:
\begin{lemma}[Balog-Szemer\'edi-Gowers]\label{entropic-bsg}
  \lean{ent_bsg}\leanok
  Let $A,B$ be $G$-valued random variables on $\Omega$, and set $Z := A+B$.
Then
\begin{equation}\label{2-bsg-takeaway} \sum_{z}  \mathbb{P}[Z=z] d[(A | Z = z); (B | Z = z)] \leq 3  \mathbb{I}[A:B] + 2 \mathbb{H}[Z] - \mathbb{H}[A] - \mathbb{H}[B]. \end{equation}
\end{lemma}

n44273.content:
\begin{proof}
  \uses{cond-indep-exist, cond-trial-ent, conditional-entropy-def,submodularity, copy-ent, relabeled-entropy, add-entropy, ruz-indep}
  \leanok
Let $(A_1, B_1)$ and $(A_2, B_2)$ (and $Z'$, which by abuse of notation we call $Z$) be conditionally independent trials of $(A,B)$ relative to $Z$ as produced by \Cref{cond-indep-exist}, thus $(A_1,B_1)$ and $(A_2,B_2)$ are coupled through the random variable $A_1 + B_1 = A_2 + B_2$, which by abuse of notation we shall also call $Z$.

Observe from \Cref{ruz-indep} that the left-hand side of~\eqref{2-bsg-takeaway} is
\begin{equation}\label{lhs-to-bound}
\mathbb{H}[A_1 - B_2| Z] - \mathbb{H}[A_1 | Z]/2 - \mathbb{H}[B_2 | Z]/2.
\end{equation}
since, crucially, $(A_1 | Z=z)$ and $(B_2 | Z=z)$ are independent for all $z$.

Applying submodularity (\Cref{alt-submodularity}) gives
\begin{equation}\label{bsg-31} \begin{split}
&\mathbb{H}[A_1 - B_2] + \mathbb{H}[A_1 - B_2, A_1, B_1] \\
&\qquad \leq \mathbb{H}[A_1 - B_2, A_1] + \mathbb{H}[A_1 - B_2,B_1].
\end{split}\end{equation}
We estimate the second, third and fourth terms appearing here.
First note that, by \Cref{cond-trial-ent} and \Cref{relabeled-entropy} (noting that the tuple $(A_1 - B_2, A_1, B_1)$  determines the tuple $(A_1, A_2, B_1, B_2)$ since $A_1+B_1=A_2+B_2$)
\begin{equation}\label{bsg-24} \mathbb{H}[A_1 - B_2, A_1, B_1] = \mathbb{H}[A_1, B_1, A_2, B_2,Z] = 2\mathbb{H}[A,B] - \mathbb{H}[Z].\end{equation}
Next observe that
\begin{equation}\label{bsg-23} \mathbb{H}[A_1 - B_2, A_1] = \mathbb{H}[A_1, B_2] \leq \mathbb{H}[A] + \mathbb{H}[B].
\end{equation}
Finally, we have
\begin{equation}\label{bsg-25} \mathbb{H}[A_1 - B_2, B_1] = \mathbb{H}[A_2 - B_1, B_1] = \mathbb{H}[A_2, B_1] \leq \mathbb{H}[A] + \mathbb{H}[B].\end{equation}
Substituting~\eqref{bsg-24},~\eqref{bsg-23} and~\eqref{bsg-25} into~\eqref{bsg-31} yields
\[\mathbb{H}[A_1 - B_2] \leq 2 \mathbb{I}[A:B] + \mathbb{H}[Z]\] and so by \Cref{cond-reduce}
\[\mathbb{H}[A_1 - B_2 | Z]  \leq 2 \mathbb{I}[A:B] + \mathbb{H}[Z].\]
Since
\begin{align*} \mathbb{H}[A_1 | Z] & = \mathbb{H}[A_1, A_1 + B_1] - \mathbb{H}[Z] \\ & = \mathbb{H}[A,B] - \mathbb{H}[Z] \\ & = \mathbb{H}[Z] -  \mathbb{I}[A:B] - 2 \mathbb{H}[Z]- \mathbb{H}[A]-\mathbb{H}[B]\end{align*}
and similarly for $\mathbb{H}[B_2 | Z]$, we see that~\eqref{lhs-to-bound} is bounded by
$3 \mathbb{I}[A:B] + 2\mathbb{H}[Z]-\mathbb{H}[A]-\mathbb{H}[B]$ as claimed.
\end{proof}

n44274.content:
\begin{lemma}[Upper bound on conditioned Ruzsa distance]\label{cond-dist-fact}
  \uses{cond-dist-def, information-def}
  \lean{condRuzsaDist_le, condRuzsaDist_le'}\leanok
  Suppose that $(X, Z)$ and $(Y, W)$ are random variables, where $X, Y$ take values in an abelian group. Then
  \[   d[X  | Z;Y | W] \leq d[X ; Y] + \tfrac{1}{2}  \mathbb{I}[X : Z] + \tfrac{1}{2}  \mathbb{I}[Y : W].\]
  In particular,
  \[   d[X ;Y | W] \leq d[X ; Y] + \tfrac{1}{2}  \mathbb{I}[Y : W].\]
\end{lemma}

n44275.content:
\begin{proof}
\uses{cond-dist-alt, independent-exist, cond-reduce}\leanok
Using \Cref{cond-dist-alt} and \Cref{independent-exist}, if $(X',Z'), (Y',W')$ are independent copies of the variables $(X,Z)$, $(Y,W)$, we have
\begin{align*}
  d[X  | Z; Y | W]&= \mathbb{H}[X'-Y'|Z',W'] - \tfrac{1}{2} \mathbb{H}[X'|Z'] - \tfrac{1}{2}H[Y'|W'] \\
                       &\le \mathbb{H}[X'-Y']- \tfrac{1}{2} \mathbb{H}[X'|Z'] - \tfrac{1}{2}H[Y'|W'] \\
                       &= d[X';Y'] + \tfrac{1}{2}  \mathbb{I}[X' : Z'] + \tfrac{1}{2}  \mathbb{I}[Y' : W'].
\end{align*}
Here, in the middle step we used \Cref{cond-reduce}, and in the last step we used \Cref{ruz-dist-def} and \Cref{information-def}.
\end{proof}

n44276.content:
\begin{lemma}[Comparison of Ruzsa distances, I]\label{first-useful}
  \lean{condRuzsaDist_diff_le, condRuzsaDist_diff_le', condRuzsaDist_diff_le'', condRuzsaDist_diff_le'''}\leanok
  Let $X, Y, Z$ be random variables taking values in some abelian group of characteristic $2$, and with $Y, Z$ independent. Then we have
  \begin{align}\nonumber d[X ; Y + Z] -d[X ; Y] &  \leq \tfrac{1}{2} (\mathbb{H}[Y+ Z] - \mathbb{H}[Y]) \\ & = \tfrac{1}{2} d[Y; Z] + \tfrac{1}{4} \mathbb{H}[Z] - \tfrac{1}{4} \mathbb{H}[Y]. \label{lem51-a} \end{align}
  and
  \begin{align}\nonumber
  d[X ;Y|Y+ Z] - d[X ;Y] & \leq \tfrac{1}{2} \bigl(\mathbb{H}[Y+ Z] - \mathbb{H}[Z]\bigr) \\ & = \tfrac{1}{2} d[Y;Z] + \tfrac{1}{4} \mathbb{H}[Y] - \tfrac{1}{4} \mathbb{H}[Z].
    \label{ruzsa-3}
  \end{align}
  \end{lemma}

n44277.content:
\begin{proof}
    \uses{ruz-copy, independent-exist, kv, ruz-indep, relabeled-entropy, cond-dist-fact}\leanok
  We first prove~\eqref{lem51-a}. We may assume (taking an independent copy, using \Cref{independent-exist} and \Cref{ruz-copy}, \ref{ruz-indep}) that $X$ is independent of $Y, Z$. Then we have
  \begin{align*}  d[X ;Y+ Z] & - d[X ;Y] \\ & = \mathbb{H}[X + Y + Z] - \mathbb{H}[X + Y] - \tfrac{1}{2}\mathbb{H}[Y + Z] + \tfrac{1}{2} \mathbb{H}[Y].\end{align*}
  Combining this with \Cref{kv} gives the required bound. The second form of the result is immediate \Cref{ruz-indep}.

  Turning to~\eqref{ruzsa-3}, we have from \Cref{information-def} and \Cref{relabeled-entropy}
  \begin{align*}  \mathbb{I}[Y : Y+ Z] & = \mathbb{H}[Y] + \mathbb{H}[Y + Z] - \mathbb{H}[Y, Y + Z] \\ & = \mathbb{H}[Y] + \mathbb{H}[Y + Z] - \mathbb{H}[Y, Z]  = \mathbb{H}[Y + Z] - \mathbb{H}[Z],\end{align*}
  and so~\eqref{ruzsa-3} is a consequence of \Cref{cond-dist-fact}. Once again the second form of the result is immediate from \Cref{ruz-indep}.
\end{proof}

n44278.content:
\begin{lemma}[Comparison of Ruzsa distances, II]\label{second-useful}
  \lean{condRuzsaDist_diff_ofsum_le}\leanok
  Let $X, Y, Z, Z'$ be random variables taking values in some abelian group, and with $Y, Z, Z'$ independent. Then we have
  \begin{align}\nonumber
  & d[X ;Y + Z | Y + Z + Z'] - d[X ;Y] \\ & \qquad \leq \tfrac{1}{2} ( \mathbb{H}[Y + Z + Z'] + \mathbb{H}[Y + Z] - \mathbb{H}[Y] - \mathbb{H}[Z']).\label{7111}
  \end{align}
  \end{lemma}

n44279.content:
\begin{proof}
    \uses{first-useful}\leanok
  By \Cref{first-useful} (with a change of variables) we have
  \[d[X ; Y + Z | Y + Z + Z'] - d[X ; Y + Z] \leq \tfrac{1}{2}( \mathbb{H}[Y + Z + Z'] - \mathbb{H}[Z']).\]
  Adding this to~\eqref{lem51-a} gives the result.
  \end{proof}

n44280.content:
\begin{definition}[Symmetry group]\label{sym-group-def}
\lean{symmGroup}\leanok
If $X$ is a $G$-valued random variable, then the symmetry group $\mathrm{Sym}[X]$ is the set of all $h \in G$ such that $X +h$ has the same distribution as $X$.
\end{definition}

n44281.content:
\begin{lemma}[Symmetry group is a group]\label{sym-group}\uses{sym-group-def}
\lean{symmGroup}\leanok
If $X$ is a $G$-valued random variable, then $\mathrm{Sym}[X]$ is a subgroup of $G$.
\end{lemma}

n44283.content:
\begin{lemma}[Zero Ruzsa distance implies large symmetry group]\label{zero-large}
  \lean{sub_mem_symmGroup}\leanok  If $X$ is a $G$-valued random variable such that
  $d[X ;X]=0$, and $x,y \in G$ are such that $P[X=x], P[X=y]>0$, then $x-y \in \mathrm{Sym}[X]$.
\end{lemma}

n44284.content:
\begin{proof}
  \uses{ruz-indep, ruz-copy, relabeled-entropy-cond,vanish-entropy, alternative-mutual, independent-exist,sym-group-def}\leanok
   Let $X_1,X_2$ be independent copies of $X$ (from \Cref{independent-exist}). Let $A$ denote the range of $X$.  From \Cref{ruz-indep} and \Cref{ruz-copy} we have
  $$ \mathbb{H}[X_1-X_2] = \mathbb{H}[X_1].$$
Observe from \Cref{relabeled-entropy-cond} that
$$ \mathbb{H}[X_1-X_2|X_2] = \mathbb{H}[X_1|X_2] = \mathbb{H}[X_1]$$
and hence by \Cref{alternative-mutual}
$$ \mathbb{I}[X_1-X_2 : X_1] = 0.$$
By \Cref{vanish-entropy}, $X_1-X_2$ and $X_1$ are therefore independent, thus the law of $(X_1-X_2|X_1=x)$ does not depend on $x \in A$. The claim follows.
\end{proof}

n44285.content:
\begin{lemma}[Translate is uniform on symmetry group]\label{sym-zero}
\lean{isUniform_sub_const_of_rdist_eq_zero}\leanok
  If $X$ is a $G$-valued random variable with $d[X ;X]=0$, and $x_0$ is a point with $P[X=x_0] > 0$, then $X-x_0$ is uniformly distributed on $\mathrm{Sym}[X]$.
\end{lemma}

n44287.content:
\begin{lemma}[Symmetric 100\% inverse theorem]\label{lem:100pc-self}
  \lean{exists_isUniform_of_rdist_self_eq_zero}\leanok
  Suppose that $X$ is a $G$-valued random variable such that
  $d[X ;X]=0$. Then there exists a subgroup $H \leq G$ such that $d[X ;U_H] = 0$.
\end{lemma}

n44288.content:
\begin{proof}\uses{sym-group, sym-zero}\leanok
Take $H$ to be the symmetry group of $X$, which is a group by \Cref{sym-group}. From \Cref{sym-zero}, $X-x_0$ is uniform on $H$, and $d[X ;X-x_0] = d[X ;X] \leq 0$, and the claim follows.
\end{proof}

n44289.content:
\begin{corollary}[General 100\% inverse theorem]\label{lem:100pc}
  \lean{exists_isUniform_of_rdist_eq_zero}\leanok
  Suppose that $X_1,X_2$ are $G$-valued random variables such that
  $d[X_1;X_2]=0$. Then there exists a subgroup $H \leq G$ such that $d[X_1;U_H] = d[X_2;U_H] = 0$.
\end{corollary}

n44290.content:
\begin{proof}\uses{lem:100pc-self,ruzsa-triangle, ruzsa-nonneg}\leanok
Using \Cref{ruzsa-triangle} and \Cref{ruzsa-nonneg} we have $d[X_1;X_1]=0$, hence by \Cref{lem:100pc-self} $d[X_1;U_H]=0$ for some subgroup $H$.  By \Cref{ruzsa-triangle} and \Cref{ruzsa-nonneg} again we also have $d[X_2;U_H]$ as required.
\end{proof}

n44293.content:
\begin{corollary}\label{fibring-ineq}
 \lean{rdist_of_hom_le} \leanok
If $\pi:G\to H$ is a homomorphism of additive groups and $X,Y$ are $G$-valued random variables then
\[d[X;Y]\geq d[\pi(X);\pi(Y)].\]
\end{corollary}

n44294.content:
\begin{proof}
\uses{fibring-ident, ruzsa-nonneg}\leanok
By \Cref{fibring-ident} and the nonnegativity of conditional Ruzsa distance (from \Cref{ruzsa-nonneg}) we have
\[d[X;Y]\geq d[\pi(X);\pi(Y)]+d[X\mid \pi(X);Y\mid \pi(Y)].\]
The inequality follows from $d[X\mid \pi(X);Y\mid \pi(Y)]\geq 0$ (\Cref{ruzsa-nonneg}).
\end{proof}

n44295.content:
\begin{corollary}[Specific fibring identity]\label{cor-fibre}
  \lean{sum_of_rdist_eq}\leanok
  Let $Y_1,Y_2,Y_3$ and $Y_4$ be independent $G$-valued random variables.
  Then
\begin{align*}
  & d[Y_1+Y_3; Y_2+Y_4] + d[Y_1|Y_1+Y_3; Y_2|Y_2+Y_4] \\
  &\qquad + \mathbb{I}[Y_1+Y_2 : Y_2 + Y_4 | Y_1+Y_2+Y_3+Y_4] = d[Y_1; Y_2] + d[Y_3; Y_4].
\end{align*}
\end{corollary}

n44298.content:
\begin{definition}[$\tau$ functional]\label{tau-def}
  \uses{eta-def, ruz-dist-def}
  \lean{tau}\leanok
If $X_1,X_2$ are two $G$-valued random variables, then
$$  \tau[X_1; X_2] := d[X_1; X_2] + \eta  d[X^0_1; X_1] + \eta d[X^0_2; X_2].$$
\end{definition}

n44299.content:
\begin{lemma}[$\tau$ depends only on distribution]\label{tau-copy}\leanok
  \uses{tau-def}
  \lean{ProbabilityTheory.IdentDistrib.tau_eq}  If $X'_1, X'_2$ are copies of $X_1,X_2$, then $\tau[X'_1;X'_2] = \tau[X_1;X_2]$.
\end{lemma}

n44301.content:
\begin{definition}[$\tau$-minimizer]\label{tau-min-def}
\uses{tau-def}
\lean{TauMinimizes}\leanok
A pair of $G$-valued random variables $X_1, X_2$ are said to be a $\tau$-minimizer if one has
  $$\tau[X_1;X_2] \leq \tau[X'_1;X'_2]
  $$
for all $G$-valued random variables $X'_1, X'_2$.
\end{definition}

n44302.content:
\begin{proposition}[$\tau$ has minimum]\label{tau-min}\uses{tau-min-def}
  \lean{tau_minimizer_exists}\leanok
A pair $X_1, X_2$ of $\tau$-minimizers exist.
\end{proposition}

n44304.content:
\begin{lemma}[Distance lower bound]\label{distance-lower}
  \uses{tau-min-def}\leanok
  \lean{distance_ge_of_min}
  For any $G$-valued random variables $X'_1,X'_2$, one has
$$ d[X'_1;X'_2] \geq k - \eta (d[X^0_1;X'_1] - d[X^0_1;X_1] ) - \eta (d[X^0_2;X'_2] - d[X^0_2;X_2] ).$$
\end{lemma}

n44306.content:
\begin{lemma}[Conditional distance lower bound]\label{cond-distance-lower}
  \uses{tau-min-def, cond-dist-def}
  \lean{condRuzsaDistance_ge_of_min}\leanok
  For any $G$-valued random variables $X'_1,X'_2$ and random variables $Z,W$, one has
$$ d[X'_1|Z;X'_2|W] \geq k - \eta (d[X^0_1;X'_1|Z] - d[X^0_1;X_1] ) - \eta (d[X^0_2;X'_2|W] - d[X^0_2;X_2] ).$$
\end{lemma}

n44308.content:
\begin{lemma}[Fibring identity for first estimate]\label{first-fibre}
  \lean{rdist_add_rdist_add_condMutual_eq}\leanok
  We have
  \begin{align*}
    &   d[X_1+\tilde X_2;X_2+\tilde X_1] + d[X_1|X_1+\tilde X_2; X_2|X_2+\tilde X_1] \\
    &\quad + \mathbb{I}[X_1+ X_2 : \tilde X_1 + X_2 \,|\, X_1 + X_2 + \tilde X_1 + \tilde X_2] = 2k.
  \end{align*}
\end{lemma}

n44310.content:
\begin{lemma}[Lower bound on distances]\label{first-dist-sum}
  \lean{rdist_of_sums_ge}\leanok
  We have
  \begin{align*}
    d[X_1+\tilde X_2; X_2+\tilde X_1] \geq k &- \eta (d[X^0_1; X_1+\tilde X_2] - d[X^0_1; X_1]) \\& \qquad- \eta (d[X^0_2; X_2+\tilde X_1] - d[X^0_2; X_2])
  \end{align*}
\end{lemma}

n44312.content:
\begin{lemma}[Lower bound on conditional distances]\label{first-cond}
  \lean{condRuzsaDist_of_sums_ge}\leanok
  We have
  \begin{align*}
    & d[X_1|X_1+\tilde X_2; X_2|X_2+\tilde X_1]  \\  & \qquad\quad \geq k - \eta (d[X^0_1; X_1 | X_1 + \tilde X_2] - d[X^0_1; X_1]) \\
    & \qquad\qquad\qquad\qquad  - \eta(d[X^0_2; X_2 | X_2 + \tilde X_1] - d[X^0_2; X_2]).
  \end{align*}
\end{lemma}

n44314.content:
\begin{lemma}[Upper bound on distance differences]\label{first-upper}\leanok
  \lean{diff_rdist_le_1, diff_rdist_le_2, diff_rdist_le_3, diff_rdist_le_4}
  We have
  \begin{align*}
    d[X^0_1; X_1+\tilde X_2] - d[X^0_1; X_1] &\leq \tfrac{1}{2} k + \tfrac{1}{4} \mathbb{H}[X_2] - \tfrac{1}{4} \mathbb{H}[X_1]\\
    d[X^0_2;X_2+\tilde X_1] - d[X^0_2; X_2] &\leq \tfrac{1}{2} k + \tfrac{1}{4} \mathbb{H}[X_1] - \tfrac{1}{4} \mathbb{H}[X_2], \\
    d[X_1^0;X_1|X_1+\tilde X_2] - d[X_1^0;X_1] &\leq \tfrac{1}{2} k + \tfrac{1}{4} \mathbb{H}[X_1] - \tfrac{1}{4} \mathbb{H}[X_2]  \\
    d[X_2^0; X_2|X_2+\tilde X_1] - d[X_2^0; X_2] &\leq \tfrac{1}{2}k + \tfrac{1}{4} \mathbb{H}[X_2] - \tfrac{1}{4} \mathbb{H}[X_1].
  \end{align*}
\end{lemma}

n44318.content:
\begin{lemma}[Entropy bound on quadruple sum]\label{foursum-bound}
  \lean{ent_ofsum_le}\leanok
  With the same notation, we have
  \begin{equation}
    \label{HS-bound}
    \mathbb{H}[X_1+X_2+\tilde X_1+\tilde X_2] \le \tfrac{1}{2} \mathbb{H}[X_1]+\tfrac{1}{2} \mathbb{H}[X_2] + (2 + \eta) k - I_1.
  \end{equation}
\end{lemma}

n44320.content:
\begin{lemma}[Distance between sums]\label{dist-sums}
  \lean{rdist_of_sums_ge'}\leanok
We have
$$ d[X_1+\tilde X_1; X_2+\tilde X_2] \geq k - \frac{\eta}{2} ( d[X_1; X_1] + d[X_2;X_2] ).$$
\end{lemma}

n44323.content:
\begin{proof}
\uses{ruz-indep, foursum-bound, dist-sums}\leanok
We may use \Cref{ruz-indep} to expand
  \begin{align*}
   & d[X_1+\tilde X_1;X_2+\tilde X_2] \\ &= \mathbb{H}[X_1+\tilde X_1 + X_2 + \tilde X_2]  - \tfrac{1}{2} \mathbb{H}[X_1+\tilde X_1] - \tfrac{1}{2} \mathbb{H}[X_2+\tilde X_2] \\
    &= \mathbb{H}[X_1+\tilde X_1 + X_2 + \tilde X_2]  - \tfrac{1}{2} \mathbb{H}[X_1] - \tfrac{1}{2} \mathbb{H}[X_2]  \\ & \qquad\qquad\qquad   - \tfrac{1}{2} \left( d[X_1;X_1] + d[X_2; X_2] \right),
  \end{align*}
  and hence by \Cref{foursum-bound}
  \[
    d[X_1+\tilde X_1; X_2+\tilde X_2] \leq (2+\eta) k - \tfrac{1}{2} \left( d[X_1;X_1] + d[X_2;X_2] \right) - I_1.
  \]
  Combining this bound with \Cref{dist-sums} we obtain
  the result.
\end{proof}

