n44352.content:
\begin{proof} \uses{entropic-bsg,distance-lower}\leanok
  We apply \Cref{entropic-bsg} with $(A,B) = (T_1, T_2)$ there.
  Since $T_1 + T_2 = T_3$, the conclusion is that
  \begin{align} \nonumber \sum_{t_3} \mathbb{P}[T_3 = t_3] & d[(T_1 | T_3 = t_3); (T_2 | T_3 = t_3)] \\ & \leq 3 \mathbb{I}[T_1 : T_2] + 2 \mathbb{H}[T_3] - \mathbb{H}[T_1] - \mathbb{H}[T_2].\label{bsg-t1t2'}
  \end{align}
  The right-hand side in~\eqref{bsg-t1t2'} can be rearranged as
  \begin{align*} & 2( \mathbb{H}[T_1] + \mathbb{H}[T_2] + \mathbb{H}[T_3]) - 3 \mathbb{H}[T_1,T_2] \\ & = 2(\mathbb{H}[T_1] + \mathbb{H}[T_2] + \mathbb{H}[T_3]) - \mathbb{H}[T_1,T_2] - \mathbb{H}[T_2,T_3] - \mathbb{H}[T_1, T_3] = \delta,\end{align*}
  using the fact (from \Cref{relabeled-entropy}) that all three terms $\mathbb{H}[T_i,T_j]$ are equal to $\mathbb{H}[T_1,T_2,T_3]$ and hence to each other.
  We also have
  \begin{align*}
  &  \sum_{t_3} P[T_3 = t_3] \bigl(d[X^0_1; (T_1 | T_3=t_3)] - d[X^0_1;X_1]\bigr) \\
  &\quad = d[X^0_1; T_1 | T_3] - d[X^0_1;X_1]
  \end{align*}
  and similarly
  \begin{align*}
  &  \sum_{t_3} \mathbb{P}[T_3 = t_3] (d[X^0_2;(T_2 | T_3=t_3)] - d[X^0_2; X_2]) \\
  &\quad\quad\quad\quad\quad\quad \leq d[X^0_2;T_2|T_3] - d[X^0_2;X_2].
  \end{align*}
  Putting the above observations together, we have
  \begin{align*}
   \sum_{t_3} \mathbb{P}[T_3=t_3] \psi[(T_1 | T_3=t_3); (T_2 | T_3=t_3)] \leq \delta + \eta (d[X^0_1;T_1|T_3]-d[X^0_1;X_1]) \\
     + \eta (d[X^0_2;T_2|T_3]-d[X^0_2;X_2])
   \end{align*}
where we introduce the notation
\[\psi[Y_1; Y_2] := d[Y_1;Y_2] +  \eta (d[X_1^0;Y_1] - d[X_1^0;X_1]) + \eta(d[X_2^0;Y_2] - d[X_2^0;X_2]).\]
On the other hand, from \Cref{distance-lower} we have $k \leq \psi[Y_1;Y_2]$, and the claim follows.
\end{proof}

